cat > /etc/nginx/conf.d/inventory-lb.conf <<'EOF'
upstream inventory_backends {
    server 10.100.47.11:8080;
    server 10.100.47.12:8080;
}

server {
    listen 80;
    server_name _;

    location / {
        proxy_pass http://inventory_backends;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}
EOF
grep -q "listen.*80.*default_server" /etc/nginx/nginx.conf && echo HAS_DEFAULT || echo NO_DEFAULT_CONFLICT_CHECK_NEEDED

